Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Root ".orcaly-cart-backup-$Timestamp"
$PatchFile = Join-Path $env:TEMP "orcaly-responsive-cart-v3-$Timestamp.js"

$TouchedFiles = @(
  "components\public-site\FoodMarketplaceCatalog.tsx",
  "components\public-site\SegmentMarketplaceCatalog.tsx",
  "components\checkout\CheckoutClient.tsx"
)

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

foreach ($RelativePath in $TouchedFiles) {
  $Source = Join-Path $Root $RelativePath

  if (-not (Test-Path -LiteralPath $Source)) {
    throw "Arquivo não encontrado: $RelativePath"
  }

  $Destination = Join-Path $BackupDir $RelativePath
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Restore-OrcalyCartBackup {
  Write-Host ""
  Write-Host "Restaurando os três arquivos anteriores..." -ForegroundColor Yellow

  foreach ($RelativePath in $TouchedFiles) {
    $Source = Join-Path $BackupDir $RelativePath
    $Destination = Join-Path $Root $RelativePath

    if (Test-Path -LiteralPath $Source) {
      Copy-Item -LiteralPath $Source -Destination $Destination -Force
    }
  }
}

try {
  $EncodedPatch = @'

'@

  $PatchBytes = [Convert]::FromBase64String(($EncodedPatch -replace "\s", ""))
  [IO.File]::WriteAllBytes($PatchFile, $PatchBytes)

  Write-Host "==> Remodelando carrinho responsivo" -ForegroundColor Cyan
  node $PatchFile
  $PatchExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "PATCH_NODE_EXIT_CODE=$PatchExitCode" -ForegroundColor Yellow

  if ($PatchExitCode -ne 0) {
    throw "O patch do carrinho falhou."
  }

  $Checks = @(
    @("components\public-site\FoodMarketplaceCatalog.tsx", "ORCALY_RESPONSIVE_FOOD_CART_V3"),
    @("components\public-site\FoodMarketplaceCatalog.tsx", "Continuar para pagamento"),
    @("components\public-site\SegmentMarketplaceCatalog.tsx", "ORCALY_RESPONSIVE_SEGMENT_CART_V3"),
    @("components\public-site\SegmentMarketplaceCatalog.tsx", "Cupom de desconto"),
    @("components\checkout\CheckoutClient.tsx", "ORCALY_MOBILE_CHECKOUT_ACTION_V3"),
    @("components\checkout\CheckoutClient.tsx", "Gerar pagamento"),
    @("components\checkout\CheckoutClient.tsx", 'id="checkout-payment-section"')
  )

  Write-Host ""
  Write-Host "==> Verificando o novo carrinho" -ForegroundColor Cyan

  foreach ($Check in $Checks) {
    $Found = Select-String `
      -LiteralPath (Join-Path $Root $Check[0]) `
      -Pattern $Check[1] `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Found) {
      throw "Verificação falhou: $($Check[0]) -> $($Check[1])"
    }

    Write-Host "[OK] $($Check[1])" -ForegroundColor Green
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan
  git diff --check -- @($TouchedFiles)

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  Remove-Item -LiteralPath (Join-Path $Root ".next") -Recurse -Force -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan
  npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $BackupDir -Recurse -Force
  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "CARRINHO RESPONSIVO APROVADO" -ForegroundColor Magenta
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "Celular: folha inferior com ação fixa"
  Write-Host "PC: painel lateral com cabeçalho e rodapé fixos"
  Write-Host "Cupom: sempre visível"
  Write-Host "Pagamento: botão sempre acessível"
  Write-Host "Checkout: Gerar pagamento fixo no celular"
  Write-Host ""
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Restore-OrcalyCartBackup
  Remove-Item -LiteralPath $PatchFile -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $BackupDir -Recurse -Force -ErrorAction SilentlyContinue
  throw
}
